adagrad.pseudocode:
def adagrad(theta, grad_fn, lr=0.01, eps=1e-8, steps=1000):
    G = [0.0] * len(theta)  # 파라미터별 기울기 제곱 누적
    for _ in range(steps):
        g = grad_fn(theta)
        for i in range(len(theta)):
            G[i] += g[i] ** 2
            # 많이 갱신된 파라미터일수록 보폭 축소
            theta[i] -= lr * g[i] / (G[i] + eps) ** 0.5
    return theta

