def build_adj_list(n, edges):
    adj = [[] for _ in range(n)]  # 정점마다 빈 목록
    for u, v, w in edges:
        adj[u].append((v, w))  # 방향 간선 u→v (가중치 w)
        # 무방향 그래프면 adj[v].append((u, w)) 추가
    return adj  # 공간 O(V+E)

def neighbors(adj, u):
    return adj[u]  # 인접 정점 순회 O(차수)

def has_edge(adj, u, v):
    for x, _ in adj[u]:  # 간선 존재 확인 O(차수)
        if x == v:
            return True
    return False  # 인접 행렬이면 O(1)이나 공간 O(V²)

adjacency-matrix.pseudocode:
def build_matrix(n, edges, directed=False):
    INF = float('inf')
    M = [[INF] * n for _ in range(n)]  # 간선 없음 = ∞
    for i in range(n):
        M[i][i] = 0
    for u, v, w in edges:
        M[u][v] = w
        if not directed:
            M[v][u] = w  # 무방향 → 대칭 행렬
    return M

def floyd_warshall(M):  # 밀집 그래프에 적합, O(V³)
    n = len(M)
    D = [row[:] for row in M]
    for k in range(n):  # k를 경유하는 경로 고려
        for i in range(n):
            for j in range(n):
                if D[i][k] + D[k][j] < D[i][j]:
                    D[i][j] = D[i][k] + D[k][j]
    return D

adversarial-training.pseudocode:
def adversarial_train(model, data, eps, alpha, k, epochs):
    for _ in range(epochs):
        for x, y in data:
            # 내부 최대화: PGD로 ε-볼 안 최악 섭동 탐색
            x_adv = pgd(model, x, y, eps, alpha, steps=k)
            # 외부 최소화: 원본·적대 손실 혼합 (변형 방식)
            loss = (0.5 * model.loss(x, y)
                    + 0.5 * model.loss(x_adv, y))
            model.update(grad(loss, model.params))
    return model
